from fastapi import FastAPI, File, Form, UploadFile
from fastapi.testclient import TestClient
import pytest

app = FastAPI()

@app.post("/test")
async def test_endpoint(form_data: str = Form(...), file: UploadFile = File(...)):
    return {"form_data": form_data, "file": file.filename}

client = TestClient(app)

def test_form_then_file():
    # This is the case that is reported to fail
    files = {"file": ("filename", "content")}
    data = {"form_data": "some data"}
    response = client.post("/test", data=data, files=files)
    assert response.status_code == 200
    assert response.json() == {"form_data": "some data", "file": "filename"}

def test_file_then_form():
    # This is the case that is reported to work
    @app.post("/test_reversed")
    async def test_reversed(file: UploadFile = File(...), form_data: str = Form(...)):
        return {"form_data": form_data, "file": file.filename}

    files = {"file": ("filename", "content")}
    data = {"form_data": "some data"}
    response = client.post("/test_reversed", data=data, files=files)
    assert response.status_code == 200
    assert response.json() == {"form_data": "some data", "file": "filename"}

